const Default = () => <AppHeader
    variant="filled"
    content="logo"
    title="Section title"
    titleAs="h1"
    leadingAction={SHARE}
    trailingAction={SHARE}
    logoLabel="Daily Wire" />;

const Variants = ({ content }) => (
  <div style={{ display: 'grid', gap: 24 }}>
    {APP_HEADER_VARIANTS.map((variant) => (
      <Labeled key={variant} label={variant}>
        <Frame width={WIDTH.phone}>
          <AppHeader variant={variant} content={content} title="Section title" leadingAction={SHARE} trailingAction={SHARE} />
        </Frame>
      </Labeled>
    ))}
  </div>
);

const Breakpoints = ({ variant }) => (
  <div style={{ display: 'grid', gap: 24, padding: 24, overflowX: 'auto' }}>
    {BREAKPOINTS.map((bp) => (
      <Labeled key={bp} label={`${bp} · ${WIDTH[bp]}px`}>
        <div style={{ display: 'grid', gap: 16 }}>
          <Frame width={WIDTH[bp]}>
            <AppHeader variant={variant} content="logo" />
          </Frame>
          <Frame width={WIDTH[bp]}>
            <AppHeader variant={variant} content="actions" title="Section title" leadingAction={SHARE} trailingAction={SHARE} />
          </Frame>
        </div>
      </Labeled>
    ))}
  </div>
);

const States = () => (
  <div style={{ padding: 24, overflowX: 'auto', display: 'grid', gap: 40 }}>
    <div style={statesGrid}>
      <div />
      {BREAKPOINTS.map((bp) => (
        <div key={bp} style={{ textTransform: 'capitalize', fontWeight: 600 }}>{`${bp} · ${WIDTH[bp]}`}</div>
      ))}
      {APP_HEADER_VARIANTS.flatMap((variant) =>
        LAYOUTS.map((layout) => (
          <Row key={`${variant}-${layout}`}>
            <div style={{ whiteSpace: 'nowrap', textTransform: 'capitalize' }}>{`${variant} · ${layout}`}</div>
            {BREAKPOINTS.map((bp) => (
              <Frame key={bp} width={WIDTH[bp]}>
                <AppHeader variant={variant} {...layoutProps(layout)} />
              </Frame>
            ))}
          </Row>
