        ACTION_STATES.map((s) => (
          <Row key={`${variant}-${s}`}>
            <div style={{ whiteSpace: 'nowrap', textTransform: 'capitalize' }}>{`${variant} · ${s}`}</div>
            {BREAKPOINTS.map((bp) => (
              <Frame key={bp} width={WIDTH[bp]}>
                <AppHeader
                  variant={variant}
                  content="actions"
                  title="Section title"
                  leadingAction={stateAction(s)}
                  trailingAction={stateAction(s)}
